# src/config.py
"""Configuration settings and constants for the SAT question generator."""
import os
from pathlib import Path
from dotenv import load_dotenv

# Load environment variables
load_dotenv()

# API Configuration
OPENAI_API_KEY = os.getenv('OPENAI_API_KEY')
OPENAI_MODEL = "o3-mini-2025-01-31" #gpt-4o-2024-11-20, o1-2024-12-17, 
#Options: 
#gpt-4o-2024-11-20 (standard all around, reasonable cost)
#o3-mini-2025-01-31 for cost-effective thinking (probably math)
#o1-2024-12-17 for Reading and Writing
REASONING_EFFORT ="high" #can also be "low" or "high", taking more internal reasoning tokens before producing a response; quality vs. cost.
MAX_COMPLETION_TOKENS = "25000" #- this can limit the amount of thinking so it doesn't spin forever and incur a massive cosot. 25000 is the recommended start.

# File paths
BASE_DIR = Path(__file__).parent.parent
INPUT_FILE = BASE_DIR / 'all-sat-tests-final.json'
OUTPUT_DIR = BASE_DIR / 'output'

# Ensure output directory exists
OUTPUT_DIR.mkdir(exist_ok=True)

# Question Generation Settings
DEFAULT_NUM_QUESTIONS = 5
VALID_DIFFICULTIES = ["Easy", "Medium", "Hard"]
VALID_SKILLS = [
    'Function of Sentence'
    #, 'Inferences', 'Main Idea', 'Pronouns and Modifiers', 'Punctuation', 'Referencing Data', 'Supporting Claims', "Synthesizing Notes", 'Tenses', 'Transition Words', 'Two Passages', 'Word Choice',
    #'Absolute Value', 'Algebra', 'Circles', 'Exponential Equations', 'Exponential Word Problems', 'Geometry', 'Interpreting Graphs', 'Linear Equations', 'Linear Word Problems', 'Inequality Word Problems', 'Percent', 'Polynomial Expressions', 'Probability', 'Quadratic Equations', 'Statistics', 'Systems of Equations', 'Trigonometry', 'Unit Conversions'
]

DIFFICULTY_GUIDELINES = {
    "Easy": (
        'Easy-difficulty questions should be straightforward and easy to understand for a high school student. This means there is straightforward evidence, problem solving, hints, or other information that can be used to solve the question.'),
    "Medium": (
        'Medium-difficulty questions can include traps such as:'
        'Tempting incorrect answers that may be partially correct but have an incorrect portion (i.e. correct conclusion but for the wrong reason; shows evidence of some correct Math steps but a misunderstanding or mistake in other Math steps).'
        'Misleading statements (like oversimplifications, overgeneralizations, conclusions without specific evidence, incorrect conclusions based on evidence, etc.) that tempt students to answer too quickly without fully reading the question.'
    ),
    "Hard": (
        'Hard-difficulty questions should include complex answer choice traps and nuanced reasoning. Here are additional guidelines for answer choices'
        'Incorrect answers that seem correct due to plausible reasoning but are subtly flawed (i.e. correct conclusion but for the wrong reason; shows evidence of some correct Math steps but a misunderstanding or mistake in other Math steps).'
        'Over-complication traps: Use precise, challenging academic, scientific, literary, or historic language but avoid needlessly convoluted phrasing.'
    )    
}
SKILL_PROMPTS = {
    "Absolute Value": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Easy questions should have straightforward equations (e.g., $y = |x+5|$) and solutions involving minimal steps. Medium questions might have straightforward word problems or can vary the structure of the question; they should require multiple steps, such as solving |2x - 3| = 7. Hard questions should combine absolute values with more complex algebraic manipulations or scenarios, can include real life word problems, or such as |4x + 5| = 2x + 13. \\n\\nFormatting Guidelines: Correct: 'Solve for $x$ in the equation $|2x - 3| = 7$.' Explanations would include $Case 1: 2x - 3 = 7$ (Briefly explain the operation followed by ':  ' then show the progress step by step with \\n\\n between each step). Incorrect: 'Solve for x in the equation \\(|2x - 3| = 7\\).' (Uses incorrect LaTeX syntax.)",
    "Algebra": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Algebra questions test a student's ability to manipulate variables, solve equations, or analyze algebraic relationships. Easy questions should involve single-variable linear equations, such as solving for $x$ in $3x + 5 = 11$. Easy, Medium, or Hard level equations can ask the this type of question, with increasing algebraic complexity (fractions, exponents, etc.: 'The given equation $\\frac{1}{7b} = \\frac{11x}{y}$ relates the positive numbers $b$, $x$, and $y$. Which equation correctly expresses $x$ in terms of $b$ and $y$?'. Finally, these questions can also use words to describe equations, testing students' abilities to represent words: 'The product of two positive integers is 546. If the first integer is 11 greater than twice the second integer, what is the smaller of the two integers?'",
    "Circles": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Circle questions assess understanding of properties like radius, diameter, circumference, and equations of circles and circle graph transformations vertically, horizontally, and radius size. Easy questions should involve basic formulas (e.g., find the area of a circle with radius $5$). Medium questions might involve applying the equation of a circle, $(x - h)^2 + (y - k)^2 = r^2$, to find missing values like the radius or the x or y coordinataes. Hard questions should require combining circle properties with other concepts, such as tangents or overlapping circles. \\n\\nFormatting Guidelines: Correct: 'Find the area of a circle with radius $5$.'\n- Incorrect: 'Find the area of a circle with radius five.' (Numbers should always be written as numerals in math problems.)",
    "Exponential Equations": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Easy questions should involve straightforward calculations, such as solving $2^x = 16$. Medium questions should require understanding of logarithms or manipulation of exponential expressions, such as solving $5^{x+1} = 25$. Hard questions might combine exponents with other concepts, such as fractional or negative exponents, or require simplifying nested expressions. Additionally, you can also create questions asking a student to interpret the meaning of variables or combinations of variables in the context of a word problem. \\n\\nFormatting Guidelines: Correct: 'Solve for $x$ in $2^\\frac{x}{2} = 16$.'\n- Incorrect: 'Solve for x in $2x2 = 16$.' (Improper formatting or omission of exponent symbol.)",
    "Function of Sentence": "This is the sentence or phrase whose function will need to be determined by the student. An Easy difficulty question will be straightforward (elaborating on a previous point, contradicting, providing an example, summarizing, explaining, etc. - there are many more purposes that I haven't listed). A Medium difficulty question will be more specific about the context of the question, with an incorrect answer potentially containing partially correct phrases, but having other phrases that are clearly incorrect. A Hard difficulty will use more complex language and might refer to aspects of the passage in the abstract (i.e. 'The sentence [refutes, exemplifies, illustrates, contrasts] the [problem/solution/conflict/theme discussed in the passage]' vs. overly simple language and directly referring to the context 'The sentence provides an example of the problem of trash piling up in our oceans.'). Formatting guidelines: Make sure there is an underlined sentence or phrase using '_' before and afterwards the sentence or phrase, not an asterisk '*'!. Additionally, make sure there is a question after the short paragraph separataed with \\n\\n that says something similar to this: \\n\\nWhich choice best describes the function of the underlined sentence in the overall text? or \\n\\nWhat is the primary function of the underlined sentence in the context of the paragraph?", 
    "Geometry": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Geometry questions test knowledge of shapes, angles, and spatial reasoning. Easy questions might involve finding the area or perimeter of basic shapes (e.g., rectangles, triangles). Medium questions should involve reasoning about angles, circles, or composite shapes. Hard questions can involve proofs or applying multiple geometry principles to a complex diagram. IMPORTANT NOTE: DO NOT REFERENCE A GRAPH OR FIGURE; INSTEAD PROVIDE INSTRUCTIONS OR A DESCRIPTION OF A SHAPE OR INTERSECTION OF LINES THAT THE STUDENT CAN DRAW ON THEIR PAPER AND LABEL. \\n\\nFormatting Guidelines: Correct: 'A circle has center $O$, and points $R$ and $S$ lie on the circle's radius. In triangle $ORS$, the measure of $\\angle ROS$ is $88^\\circ$. What is the measure of $\\angle RSO$, in degrees?' Another Correct example describing the shape rather than referencing a nonexistent figure: Right triangles $PQR$ and $STU$ are similar, where $P$ corresponds to $S$, and $R$ and $U$ are both right angles. If the measure of angle $Q$ is $18^\\circ$, what is the measure of angle $S$?\\n\\n- Incorrect - avoid at all costs!: 'What is the area of a the triangle in the figure above?' (The only context is what you verbally describe for the shapes and intersecting lines; there is no figure, so don't reference one. Use unicode or LaTeX to represent angles, triangles, lines, degrees, and arcs.)",
    "Inequality Word Problems": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These test a student's ability to interpret and solve inequalities based on word problems. Easy questions should involve a single inequality, such as 'If a number is greater than 3 but less than 7, what could the number be?' Medium questions might require solving compound inequalities or graphing solutions. Hard questions should involve inequalities embedded in real-world contexts, requiring multiple steps or translating complex descriptions into inequalities. \\n\\nFormatting Guidelines: Correct: 'Solve: $x + 5 \\leq 10$.'\n- Incorrect: 'Solve: x + 5 <= 10.' (Use proper LaTeX symbols for ≤ and ≥.)",
    'Inferences': "Inferences test a student's ability to make connections between evidence, claims, and conclusions. They often have similar keywords or phrases in questions that provide hints to similar keywords in answer choices - but even in Easy difficulty, they should be synonyms rather than the exact words or phrases. Medium difficulty questions should requrie context from all sentences in the passage and have slightly more complex language. Hard difficulty questions should require deep understanding of the topic discussed (though no information that isn't provided) and likely require one or two logical assumptions where a student would need to think 'if the passage says X is happening and Y is related to X, then I can infer a certain truth about Y based on X'. Key reasons why a choice might be wrong is that it isn't supported by evidence or the evidence doesn't have to lead to that conclusion; the choice could be irrelevant or not discussed; the choice could contradict the main points.",
    "Interpreting Graphs": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These questions test a student's ability to read and analyze data from graphs or charts. Easy questions should involve directly retrieving data points from HTML tables following the format of the examples. They MUST BE WITHIN THE QUESTION because there are no other pictures, graphs, or figures outside of the question. Medium questions should involve interpreting trends or performing calculations based on the tables or require a student to draw a graph on their paper. Hard questions should involve multiple graphs or combining graph analysis with external knowledge. \\n\\nFormatting Guidelines: Almost always generate an HTML table which includes information referenced by the question, and use a table border of 1 like in the example: Correct: '    The line graph shows the estimated number of chipmunks in a state park on April 1 of each year from 1989 to 1999.\\n\\n<table border='1'><thead><tr><th>Year</th><th>Estimated number of chipmunks</th></tr></thead><tbody><tr><td>1989</td><td>40</td></tr><tr><td>1990</td><td>40</td></tr><tr><td>1991</td><td>95</td></tr><tr><td>1992</td><td>100</td></tr><tr><td>1993</td><td>50</td></tr><tr><td>1994</td><td>155</td></tr><tr><td>1995</td><td>50</td></tr><tr><td>1996</td><td>95</td></tr><tr><td>1997</td><td>90</td></tr><tr><td>1998</td><td>55</td></tr><tr><td>1999</td><td>110</td></tr></tbody></table> \\n\\nBased on the table, in which year was the estimated number of chipmunks in the state park the greatest?.'\n- Incorrect: 'What is the y value at x=3 from graph' (incorrectly references a nonexistent graph that isn't provided in the question).",
    "Linear Equations": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Linear equations test a student's ability to interpret and solve equations of the form $y = mx + b$ or, rarely and at Medium or High difficulty, slope intercept form. Easy questions should involve straightforward graph interpretations (remember - there are no pictures, so you need to explain how the student can draw a graph on their own by creating a table from HTML like in the examples provided) or solving for $y$ or $x$. Medium questions might involve systems of linear equations or interpreting word problems. Hard questions could include real-world applications or combining linear equations with inequalities or other algebraic concepts. \\n\\nFormatting Guidelines: Correct: 'Find the $y$-intercept of the line $y = 2x + 5$.'\n- Incorrect: 'Find the y-intercept of the line y = 2x + 5.' (Variable names should always be italicized.)",
    "Linear Word Problems": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These questions test students' ability to translate real-world scenarios into linear equations. Easy questions should involve simple scenarios, such as calculating the total cost of items, the time it takes to do something, etc.. Medium questions should require more reasoning, like solving for an unknown in a two-variable equation or describing an equation witih words that a student needs to translate to numbers and algebra. Hard questions should involve systems of linear equations or inequalities. \\n\\nFormatting Guidelines: Correct: 'A store sells apples for $2$ dollars each and bananas for $3$ dollars each. If a customer spends $20$, how many apples and bananas could they buy?'\n- Incorrect: 'Solve for x in a store sells fruits for $2x + 3y = 20$' (confusing phrasing and lack of context or real world application).",
    "Main Idea": "These questions test a student's ability to identify the central point or theme of a passage. Easy questions should feature a passage with an explicit and straightforward main idea. Medium questions may include implicit main ideas requiring some synthesis of information. Hard questions often involve abstract or nuanced themes and less obvious wording. \\n\\nFormatting Guidelines: Good questions will introduce the text, including using italics for books and \"Quotations\" for poems or short works, followed by a double line break with single backslashes \\n\\n, then have a clear question afterwards also with a line break. Poetry examples should have single line brekas with \\n\\t to have a special font, but regular passages should NOT have line breaks between each sentence. Correct: 'The following text is from the 1923 poem \u201cBlack Finger\u201d by Angelina Weld Grimk\u00e9, a Black American writer. A cypress is a type of evergreen tree. \\n\\n\tI have just seen a most beautiful thing, \n\tSlim and still,\n\tAgainst a gold, gold sky, \n\tA straight black cypress, \n\tSensitive,\n\tExquisite,\n\tA black finger \n\tPointing upwards.\n\tWhy, beautiful still finger, are you black? \n\tAnd why are you pointing upwards?\\n\\nWhich choice best describes the overall structure of the text?'\\n\\n- Incorrect: 'Tommy went to town.\\n\\nTommy bought a sandwich.' (incorrect line breaks within passage and missing line break before final question, no introduction of text, missing a final question of 'Which choice best describes the overall structure/main idea of the text?'.",
    "Percent": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Percent questions assess students' understanding of percentages, such as calculating percentage increases, decreases, or proportions. Easy questions should involve single-step calculations like finding 20\\% of a number or what increasing or decreasing a number by x\\% would do. Medium questions can combine percentages with another operation (e.g., finding the percent change). Hard questions might involve multi-step problems or abstract applications.\\n\\nFormatting Guidelines: You must use a single backslash to escacape the percent symbol to display properly. '\\%'- Correct: 'If a $50$ item is discounted by $20\\%$, what is the final price?'\n- Incorrect: 'Calculate percent change 50 to 40' (missing percent formatting, no escape character, and clarity).",
    "Polynomial Expressions": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These questions test the ability to simplify, expand, and factor polynomial expressions. Easy questions involve direct operations adding or subtracting polynomials with two terms. Medium questions require multi-step operations and might include fractions where students need to simplify like terms in the numerator and denominator. Hard questions could involve higher-degree polynomials or combining multiple skills. \\n\\nFormatting Guidelines: You MUST use double backslash\\\\frac{numerator numbers}{denominator numbers} to create fractions, and they must be wrapped in '$' before and afterwards. Correct: 'Which expression is equivalent to $16x^{3} * y^{2} + 14xy$?'\n- Incorrect: 'Expand \\[x^4*yx^2\\]' (incorrect operators and incorrectly using LaTeX's block formatting which doesn't work; instead it should use $x^4*yx^2$).",
    "Probability": "Probability questions test the likelihood of events occurring. Easy questions should involve simple probabilities, such as rolling a die or flipping a coin. Medium questions might include multi-step events, such as calculating the probability of drawing two red cards from a deck without replacement. Hard questions could involve conditional probabilities or advanced scenarios, such as 'What is the probability of selecting two students from a group of 10, where one is a senior and one is a freshman?' \\n\\nFormatting Guidelines: Correct: 'What is the probability of rolling a sum of $7$ with two dice?'\n- Incorrect: 'What is the probability of rolling a sum of 7 with two dice?' (Numbers should always be italicized in math contexts.)",
    'Pronouns and Modifiers': "This tests a student's ability to match a preceding modifier or phrase match with the right pronoun or subject. A correct example of a good modifier and pronoun would be 'As ruler of the realm, King George did as he pleased'; an incorrect modifing phrase would be, 'Standing 7 feet tall, the little 5 year old boy was terrified of the massive basketball center Nikola Jokic' because the modifier suggests the little boy is 7 feet tall when in reality, the basketball player is 7 feet tall. This would be an Easy example because it is obvious that the modifier describes Nikola Jokic, not the boy, but Hard examples would include differentiating between describing a person vs. that person's actions or belongings or experiences, like 'Bringing the author fame, his books were celebrated' (correct) vs. 'Bringing the author fame, his wife celebrated him' (incorrect because 'his wife' didn't bring the author fame). Other topics to test in this category include testing 'it vs. it's; there, their, and they're; and who's vs. whose. Easy questions should be obviou",
    'Punctuation': "This assesses a student's ability to use commas, semicolons, colons, hyphens, parentheses, and apostrophes. Questions should assess students' abililties to 1) join (or choose not to separate with a period and new sentence) two independent clauses using conjunctions, commas, or semicolons; 2) Decide how and when to join an independent and dependent clause using various punctuation marks and especially commas, colons, semicolons, and hyphens; 3) paralellism in sentence structure (Good example: 'Harry likes to run, to play, and to sleep'; Incorrect: 'Harry likes running, to play, and to sleep'. Other examples can use transition words for comparison like 'while..., actually... Similarly, while...); 4) Use of apostrophes for possesive nouns and plural possessive (Good example: the boys' heights (plural) vs. the boy's height (singular); 5) Removing unnecessary wordiness or awkward phrasing because the most concise, grammatically correct answer that doesn't omit essential information should be correct: (Easy difficulty incorrect answer: 'The cat that belongs to the professor died; because of this event, the professor was sad.'Correct answer: 'The professor's cat died, so the he was sad.'). When testing and explaining the use of colons, they must have an independent clause before them and then a list, explanation, or definition afterward: 'I have 3 favorite foods: mac'n cheese, burgers, and pizza' (correct) vs. 'My 3 favorite foods are: mac'n cheese, burgers, and pizza' (incorrect because the preceding phrase before the colon is no longer an independent clause).' Easy difficulty questions will often have awkward punctuation or wording for incorrect answer choices and clearly correct answers, while Medium difficulty questions will often ask about less frequently used punctuation marks (semicolons, colons, hyphens, apostrophes) in easier use cases or commas in complex use cases (like introductory phrases, modifiers, non-essential clauses, or using them in combination with a semicolon or colon). Hard difficulty questions will require students to apply multiple grammar rules in a phrase where some might be correct, but there must be at least one incorrectly used punctuation for the incorrect answer choices. Look closely at the examples questions for further examples. \n\nFinally, I recommend you first create a correct sentence using a certain punctuation or grammar rule first. Then, move the phrase containing the correctly used punctuation mark into one of the answer choices and replace it with a blank: ' ________ ' in the question because a common error you MUST AVOID is making a correct sentence in the question with no correct answer choices.",
    "Quadratic Equations": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Quadratic equations test a student's ability to solve equations of the form $ax^2 + bx + c = 0$. Easy questions might involve factoring or using the quadratic formula with simple roots. Medium questions could involve completing the square or solving quadratics with irrational roots. Hard questions might include complex roots or real-world applications of quadratic equations. \\n\\nFormatting Guidelines: Correct: 'Solve for $x$: $x^2 - 5x + 6 = 0$.'\n- Incorrect: 'Solve for x: x^2 - 5x + 6 = 0.' (Variables should always be italicized, and equations formatted in LaTeX.)",
    "Referencing Data": "These questions involve interpreting data from HTML tables. Easy questions should briefly provide context for a table with a heading and labels, then directly ask for specific values in the provided HTML table. Medium questions require comparisons, interpretations, or minor calculations from a provided table. Hard questions might involve synthesizing data from within an attached paragraph as well as the table. \\n\\nFormatting Guidelines: Provide an introduction to the table either before or immediately afterwards; all tables should have a title or heading and labels; and all tables require a final question asking about the data within or what conclusions can be drawn based on the data or what evidence is provided to support a conclusion. Correct formatting example: 'Annual Car Production in the United States, 1910-1925<table border=\"1\">\n  <tr><th>Year</th><th>Number of cars produced</th><th>Number of companies producing cars</th></tr>\n  <tr><td>1910</td><td>123,990</td><td>320</td></tr>\n  <tr><td>1915</td><td>548,139</td><td>224</td></tr>\n  <tr><td>1920</td><td>1,651,625</td><td>197</td></tr>\n  <tr><td>1925</td><td>3,185,881</td><td>80</td></tr>\n</table>\\n\\nAnnual Car Production in the United States, 1910–1925\\n\\nA student is using the table as part of a social studies class presentation on the US auto industry in the early twentieth century. The student notes that, according to the table, from 1910 to 1925 \\n\\nWhich choice most effectively uses data from the table to complete the statement?'\n- Incorrect: 'Based on the table above, how many students participated in sports?' (No HTML table provided).",
    "Statistics": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. Statistics questions assess knowledge of mean, median, mode, range, probability, and variability. Easy questions should involve simple calculations, such as finding the mean or median of a list or dataset or identifying a number from an HTML table provided and referenced in the question. Medium questions should involve multi-step calculations, like weighted averages, interpreting data distributions, or doing calculations on multiple values in an HTML table. Hard questions should combine concepts, such as comparing two datasets or interpreting a box plot which is depicted through an HTML table.\\n\\nFormatting Guidelines: Correct: 'Data set X: 5, 9, 9, 13\nData set Y: 5, 9, 9, 13, 27\\n\\n Which statement correctly compares the mean of data set X and the mean of data set Y? Another good example of formatting with tables: Five *Eretmochelys imbricata*, a type of sea turtle, each have a nest. The table shows an original data set of the number of eggs that each turtle laid in its nest.\\n\\n<table border=\"1\">\n  <tr><th>Nest</th><th>Number of eggs</th></tr>\n  <tr><td>A</td><td>149</td></tr>\n  <tr><td>B</td><td>144</td></tr>\n  <tr><td>C</td><td>148</td></tr>\n  <tr><td>D</td><td>136</td></tr>\n  <tr><td>E</td><td>139</td></tr>\n</table>\\n\\nA sixth nest with 121 eggs is added to create a new data set. Which of the following correctly compares the means of the two data sets?'\n- Incorrect: 'Find the average in the above graph' (references a graph or table that doesn't exist - instead you should create an HTML table like in the examples provided).",
    "Supporting Claims": "These questions test the ability to identify evidence that best supports a statement or argument. Easy questions should present one or two clear pieces of evidence which logically links with the correct answer; incorrect answer should be contradicting or tangentially off topic. Medium questions can involve interpreting implied evidence. Hard questions require analyzing multiple pieces of data or subtle textual hints. \\n\\nFormatting Guidelines:- Correct Easy: 'External shopping cues are a type of marketing that uses obvious messaging\u2014a display featuring a new product, for example, or a \u201cbuy one, get one free\u201d offer\u2014to entice consumers to make spontaneous purchases. In a study, data scientist Sam K. Hui and colleagues found that this effect can also be achieved with a less obvious cue: rearranging a store\u2019s layout. The researchers explain that trying to find items in new locations causes shoppers to move through more of the store, exposing them to more products and increasing the likelihood that they\u2019ll buy an item they hadn\u2019t planned on purchasing.\\n\\nWhich response from a survey given to shoppers who made a purchase at a retail store best supports the researchers\u2019 explanation?'\n Correct Hard Example: Under normal atmospheric pressure at Earth\u2019s surface, water molecules form a tetrahedral network stabilized by hydrogen bonds between adjacent molecules. Extreme high pressure, such as can be found in deep ocean waters, destabilizes these bonds and compresses water\u2019s structure, allowing water molecules within organisms to permeate proteins and impede crucial biological functions; yet deep-sea organisms known as piezophiles have adapted to extreme pressure. Studies have found a positive correlation between the depths that various piezophiles inhabit and concentrations of a compound called trimethylamine N-oxide (TMAO) in their muscle tissues, which has led a team of researchers to hypothesize that TMAO reduces water\u2019s compressibility.\\n\\nWhich finding, if true, would most directly support the researchers\u2019 hypothesis?- Correct Answer Explanation:       \"explanation\": \"Choice D is the best answer because it presents a finding that if true would support the researchers' hypothesis that TMAO reduces water\u2019s compressibility. The text explains that at great depths in the ocean, extreme pressure compresses the molecular structure of water by destabilizing the hydrogen bonds between adjacent molecules, thereby allowing water to penetrate proteins and harm the associated organisms. However, deep-sea organisms called piezophiles have adapted to live at these depths, and previous studies show a positive correlation between the depth at which a piezophile species lives and the species level of the compound TMAO. Because this hypothesis links TMAO levels with reduced compressibility of water \u2019s tetrahedral molecular structure, a finding that TMAO helps maintain the hydrogen bonds between water molecules under high pressure would strongly support that hypothesis.\nChoice A is incorrect. Although the researchers\u2019 hypothesis suggests a relationship between TMAO and water molecules\u2019 tetrahedral molecular structure, that relationship involves TMAO helping maintain water\u2019s tetrahedral molecular structure under high pressure; as presented in the text, the hypothesis doesn\u2019t contend that water molecules are impervious to, or incapable of being penetrated by, TMAO. Choice B is incorrect because the text discusses how the molecular structure of water, not TMAO, is compressed under extreme pressure and never addresses how TMAO might be affected by such pressure. Choice C is incorrect because the researchers\u2019 hypothesis holds that water under extreme pressure is more resistant, not less, to being compressed when TMAO concentrations are higher. Moreover, the positive correlation mentioned in the text is between TMAO concentrations and the depths at which piezophiles live, not between concentrations of TMAO and the rate at which water\u2019s molecular structure compresses as pressure increases. Incorrect: 'Why is solar energy good?' (too vague and informal. Also, avoid requiring the reader to make too many assumptions; all necessary clues should be provided in the question.)",
    'Synthesizing Notes': "This assesses a student's ability to synthesize information from notes about a topic, understand their objective (given in the first sentence immediately after the bullet points 'The student wants to...'), determine which information in the bullet points is relevant and necessary to accomplish the goal, and then format the right sentence without it being awkward or overly wordy. Easy questions will have straightforward objectives with bullet points that clearly provide relevant information that can be used in the objective. Medium and Hard difficulty questions will have will have increasingly complex language and topics about scientific and social science studies, technological advancements, history, or literature, music and art. Hard difficulty questions will have more varied student objectives, some of which may be more abstract and require the student to logically connect what is being abstractly referred to (i.e. 'the claim', 'the problem', 'the study's finding') to the specific wording of the 'claim, problem or finding'. Formatting guidelines: Use \u2022 for bullet points (not '-', numbers, or combinations or 2-3 unusual characters) and do two \n with single backslashes between each bullet point. Correct example:  \\n\\n\u2022[Insert words here for each bullet point]",
    "Systems of Equations": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These questions test solving two or more equations simultaneously. Easy questions should involve substitution or elimination with whole numbers, even suggesting the method or making it obvious by setting up the equations to be solved easily. Medium questions should include fractions, decimals, or larger numbers. Hard questions should combine systems of equations with word problems. \\n\\nFormatting Guidelines: Write both equations on their own line and line up the x and y variables, using '\\n\\n' to start new lines. Correct: 'Solve the system of equations below for x: \\n\\n$2x + 3y = 6$\\n\\n$x - y = 2$.'\n- Incorrect: 'Solve the equations: 2x+3y=6, x-y=2' (missing LaTeX formatting, not starting on new lines, not using $...$ before and after the equations).",
    'Tenses': "These test students' abilities to use the correct version of a verb (present, future, past, past and present participle, conditional, and continuous tenses). There should only be one clearly correct answer, not multiple tenses that coudl work, and the context in the passage should determine this. Hard questions should particularly emphasize the context (like when an action started adn stopped - determining if it is past continuous, past partiple, present, etc.)",
    'Transition Words': 'The relationship between the two sentences and the structure of the paragraph should be considered by the student. Easy questions will have a straightforward relationship between the sentences that determine the appropriate word (i.e. similarly, for example, therefore). Harder questions may use these words as well as other transitioning phrases and include more complex language and topics.',
    "Trigonometry": "Use LaTeX for all Math expressions with two backslashes for the expressions when inside '$'. Example: $\\\\frac{...}{...}$ or $\\\\sqrt{...}$. These questions test understanding of trigonometric functions and their applications. Easy questions should involve basic ratios (e.g., sine, cosine, tangent). Medium questions should involve solving for unknowns in right triangles or applying trigonometric identities. Hard questions should include non-right triangles, radians, the unit circle, or real-world applications. \\n\\nFormatting Guidelines: Correct: 'What is the value of $\\tan \\left( \\frac{92\\pi}{3} \\right)$?.' Another correct example: Triangle $FGH$ is similar to triangle $JKL$, where angle $F$ corresponds to angle $J$ and angles $G$ and $K$ are right angles. If $\\sin(F) = \\frac{308}{317}$, what is the value of $\\sin(J)$? \\n\\n- Incorrect formattting: 'sin = 3/5; find x' (imprecise and lacks LaTeX formatting).",
    'Two Passages': "These questions require a student to understand the similarities and differences between two passages of different origin or authors with different viewpoints or backgrounds, and consider how they might interpret or respond to the other author or explain the implications, similarities, or differences between the two. Easy questions will have easily understandable vocabulary and an obvious relationship between the passages (contrasting, discussing different aspects of a similar topic, etc. - there are many more types of relationships I did not list here, so see the example questions or make up your own). Medium and Hard difficulty questions should have challenging literary, academic, professional, or scientific language, but Medium difficulty questions and answer choices should have clear logic about the ideas and features in both passages and how they relate to each other. Hard difficulty questions should refer more abstractly to aspects of the passages and have more tempting incorrect answers by having portions of them being correct but for the wrong reason (or correct reasoning but wrong answer) (i.e. Passage 1 says the government should promote free market capitalism because it makes people wealthy and life better because this maximizes overall wealth, and competition among businesses ensures consumers (general public) have the best goods and services for the best price, even if some peopple get wealthier than others. Passage 2 says government should promote free market capitalism but with regulations that ensure people of all socioeconomic statuses are treated well by businesses, even if it means businesses are inconvenienced or things are more expensive due to regulations. Incorrect Answer: 'The author of passage 1 argues for free market capitalism becasue he argues less competition means more total wealth and therefore more overall wellbeing for everyone'. Explanation why incorrect - 'While Passage 1 does argue for free market capitalism, the reasoning is incorrect...'). Formatting Guidelines: Ensure that both Passages have a header like **Passage 1:**\\n\\n and **Passage 2:**\\n\\n with double line breaks using a single backslash before each n.",
    "Unit Conversions": "These questions test a student's ability to convert between units, such as inches to feet or liters to gallons. Easy questions should involve single or two-step conversions, like converting 72 inches to yards. Medium questions should require conversions with additional operations, possibly within the context of a word problem, such as scaling a recipe or solving an engineering task. Hard questions should involve multi-step conversions or less commonly used units (note: always provide the conversion rate between all necessary units within the question). \\n\\nFormatting Guidelines: Correct: 'A certain park has an area of 11,863,808 square yards. What is the area, in square miles, of this park? (1 mile = 1,760 yards)'\n- Incorrect: '25 km/hr -> m/s' (informal symbols and lack of explanation of relation between units).",
    'Word Choice': 'These questions often have keywords or phrases in the other sentences which are synonyms, explanations, or implications of the correct word choice. Easy questions will have fairly basic vocabulary and clearly incorrect answers, and Hard questions will have advanced literary, academic, professional, or archaic vocabulary; Medium difficulty quetsions will be in the middle.'
}

